insert into typenews_content_refresh_0045 (language, mode, old_text, new_text)
values
    ('kor', 'short', '아 이게 내가 1년을 기다린 물건이구나.', '낯선 동네를 지나다가 빈 의자 옆의 온기는 평범한 순간의 소중함을 다시 알려 준다.'),
    ('kor', 'long', '생각해보자. 3개월 뒤에 상컬을 사고싶은 사람이 있어. 그런데 그 사람이 사려고 보니까 다 품절이거나 가격이 비싸 그런데 나는 이미 지금 싸게 사뒀으니까 그 사람한텐 내가 구세주인거지 양심 타령이 여기서 왜 나오는걸까.', '오랜 약속을 마치고 멀리 켜진 불빛은 서두르던 걸음을 잠시 멈추게 한다. 차를 한 잔 마시며 멀리 켜진 불빛은 작은 용기를 다시 꺼내 들게 한다. 불을 낮춘 다음 멀리 켜진 불빛은 평범한 순간의 소중함을 다시 알려 준다.'),
    ('kor', 'long', '나는 땡땡이 인데 린워크스 회원이다. 반갑다 나는 지엠케이를 30개 가지고 있고 슬슬리브도 30개 가지고있다. 그렇기 때문에 미세현미경 리뷰 ㄹㅇ 가능이고 누구보다 빠르게 남들과는 다르게 좋은 피드백을 줄수 있다.', '끝이라고 믿었던 장면에서, 세상이 조용해진 뒤에도 네 목소리만은 분명하게 들렸어, 그리고 돌아갈 수 없다면 앞으로 가자 적어도 길은 우리가 고를 수 있어.'),
    ('eng', 'short', 'Believe you can and you''re halfway there.', 'At the edge of morning, the shadow moving across the wall holds more meaning than words can explain.'),
    ('eng', 'short', 'You miss 100% of the shots you don''t take.', 'When the whole city becomes quiet, a closed door is not the end because we can still choose another road.'),
    ('eng', 'short', 'Don''t watch the clock; do what it does. Keep going.', 'After dinner, I lowered the lights and felt the hours begin to move more gently.'),
    ('eng', 'short', 'Your limitation it''s only your imagination.', 'The old password becomes unforgettable immediately after a password change.'),
    ('eng', 'short', 'Don''t wait for opportunity. Create it.', 'On a day meant for starting again, a new language becomes familiar through useful phrases before perfect sentences.'),
    ('eng', 'short', 'Be so good they can''t ignore you.', 'After the rain has passed, being a beginner means there is still plenty of room to grow.'),
    ('eng', 'short', 'Don''t stop when you''re tired. Stop when you''re done.', 'Before beginning unfamiliar work, a complex problem becomes easier when facts and guesses are separated.'),
    ('eng', 'short', 'Don''t limit your challenges. Challenge your limits.', 'An old dream may not be gone and might simply be waiting for a kinder moment to return.'),
    ('eng', 'short', 'It always seems impossible until it''s done.', 'When old friends meet again, asking how another person feels matters most when you wait patiently for the answer.'),
    ('eng', 'short', 'Don''t count the days, make the days count.', 'Trees exchange nutrients with fungi living in the soil around their roots.'),
    ('eng', 'short', 'Don''t be pushed around by the fears in your mind.', 'After a small success, a precise question can solve a blocked task faster than silent effort.'),
    ('eng', 'short', 'Opportunities don''t happen, you create them.', 'When the meeting ends, the flower beside the road becomes a gentle promise for the days ahead.'),
    ('eng', 'short', 'Don''t let yesterday take up too much of today.', 'When no answer can be certain, do not trust the words final chance because we can still write another scene.'),
    ('eng', 'short', 'You don''t have to be perfect to be amazing.', 'I arrived early and waited with a warm cup while the empty chair faced the window.'),
    ('eng', 'short', 'Don''t stop until you''re proud.', 'On a night meant for sleeping early, after three alarms, even a sleepy person becomes serious near fresh coffee.'),
    ('eng', 'short', 'Sometimes we''re tested not to show our weaknesses, but to discover our strengths.', 'Explaining a difficult idea to someone else quickly reveals the missing pieces.'),
    ('eng', 'short', 'Don''t be afraid to give up the good to go for the great.', 'When time begins to feel scarce, finding one improvement makes an ordinary day worth remembering.'),
    ('eng', 'short', 'If it doesn''t challenge you, it won''t change you.', 'When a mistake remains on your mind, a complex problem becomes easier when facts and guesses are separated.'),
    ('eng', 'short', 'Don''t wait for the perfect moment. Take the moment and make it perfect.', 'One failure never explains a whole life, while the courage to begin again can shape it.'),
    ('eng', 'short', 'Success doesn''t just find you. You have to go out and get it.', 'When gratitude needs a voice, a real apology includes a different action instead of a longer explanation.'),
    ('eng', 'short', 'Don''t quit. Suffer now and live the rest of your life as a champion.', 'Bees use the direction and speed of a dance to describe a food source.'),
    ('eng', 'short', 'Turn your can''ts into cans and your dreams into plans.', 'While walking along a different road, check difficult work in small stages before errors become expensive.'),
    ('eng', 'short', 'Don''t downgrade your dreams to fit your reality. Upgrade your conviction to match your destiny.', 'The final page of a book makes the familiar world feel new again.'),
    ('eng', 'short', 'You don''t have to be great to start, but you have to start to be great.', 'When escape becomes possible, do not trust the words final chance because we can still write another scene.'),
    ('eng', 'short', 'Don''t limit yourself. Many people limit themselves to what they think they can do.', 'When the music ended, only the clock and the soft hum of the room remained.'),
    ('eng', 'short', 'You don''t have to see the whole staircase, just take the first step.', 'When a snack becomes strangely persuasive, the promise to sleep early grows more philosophical as midnight approaches.'),
    ('eng', 'short', 'Success isn''t always about greatness. It''s about consistency.', 'As a deadline moves closer, comparing your work with yesterday is usually more useful than comparing it with others.'),
    ('eng', 'short', 'Dreams don''t work unless you do.', 'While walking along a different road, being a beginner means there is still plenty of room to grow.'),
    ('eng', 'short', 'The only bad workout is the one that didn''t happen.', 'As a deadline moves closer, finishing a quick task now can remove hours of unnecessary worry.'),
    ('eng', 'short', 'Don''t be afraid to start over. It''s a chance to build something better.', 'Every close relationship eventually asks us to understand what silence is trying to say.'),
    ('eng', 'short', 'Be proud of how far you''ve come.', 'When gratitude needs a voice, the warmth of a conversation depends on how carefully each person listens.'),
    ('eng', 'short', 'Success doesn''t come to you, you go to it.', 'When an accepted fact is questioned again, an octopus has three hearts, and two of them move blood through the gills.'),
    ('eng', 'short', 'The harder you work for something, the greater you''ll feel when you achieve it.', 'On a day meant for starting again, a useful meeting ends with clear actions instead of impressive speeches.'),
    ('eng', 'short', 'Success is not final, failure is not fatal: It is the courage to continue that counts.', 'When the meeting ends, the shadow moving across the wall settles gently into the heart.'),
    ('eng', 'short', 'It''s not whether you get knocked down; it''s whether you get up.', 'Before an important choice, if we run now the scene will stop, but one more step can change the story.'),
    ('eng', 'short', 'Don''t limit your challenges, challenge your limits.', 'The first snow changed the familiar street into a scene that felt calm and new.'),
    ('eng', 'short', 'Life is 10% what happens to us and 90% how we react to it.', 'While searching for one missing object, cleaning a drawer reveals missing objects and forgotten plans in equal numbers.'),
    ('eng', 'short', 'Be yourself; everyone else is already taken.', 'When time begins to feel scarce, a new language becomes familiar through useful phrases before perfect sentences.'),
    ('eng', 'long', 'The quiet rustle of autumn leaves beneath my feet reminds me of all the moments we''ve shared, fleeting yet unforgettable, like whispers of the past carried by the crisp breeze of a fading season.', 'After the final note, the color left in the sky brings distant feelings a little closer. The light across the river gives crowded thoughts a place to rest. When the clouds begin to clear, the warmth beside an empty chair reminds us to notice what usually passes by.'),
    ('eng', 'long', 'In the stillness of dawn, the world seems to hold its breath, and I find myself caught between yesterday''s regrets and tomorrow''s promises, clinging to the fragile hope of a new beginning.', 'When the whole city becomes quiet, when the whole city became quiet, your voice was the one sound I could find. Letting go would be easier, but I did not come here for an easy ending.'),
    ('eng', 'long', 'Morning light filters softly through the curtains, casting patterns that dance upon the floor, and in that gentle glow I find a moment of peace amid life''s chaos.', 'While standing in front of the refrigerator, new exercise clothes can look surprisingly athletic before any exercise begins. At the same time, opening the refrigerator without a plan still counts as a short expedition.'),
    ('eng', 'long', 'A solitary bird''s song breaks the silence of the early morning, a fragile sound that pierces through the stillness and awakens hope in the depths of my heart.', 'While walking along a different road, a new language becomes familiar through useful phrases before perfect sentences. At the same time, short sessions repeated over time often build stronger memories than one long session.'),
    ('eng', 'long', 'Streets glisten after the rain, reflecting neon signs that flicker like distant stars, and I wander through the city''s pulse, feeling both lost and alive in the urban symphony.', 'When the familiar method fails, rest can be a wise part of progress rather than a sign of surrender. Being a beginner means there is still plenty of room to grow.'),
    ('eng', 'long', 'The aroma of freshly baked bread wafts through the air, evoking memories of home and hearth, a simple comfort that grounds me amid the ever-changing currents of existence.', 'While taking a brief pause, when a conversation stalls, confirm what the other person meant, and important decisions are often clearer in the morning than late at night.'),
    ('eng', 'long', 'A single rose petal falls gently onto the water''s surface, creating ripples that spread outward, symbolizing how small moments of beauty can touch lives far beyond their origin.', 'When gratitude needs a voice, an old friendship remembers the path back even after a long time apart. Different opinions can begin a deeper understanding rather than end a friendship.'),
    ('eng', 'long', 'The moon''s reflection shimmers on the lake, a silver path inviting contemplation and quiet reflection, where the boundaries between self and nature blur into a harmonious whole.', 'A large cloud can contain an enormous amount of water despite its gentle shape, and bees use the direction and speed of a dance to describe a food source.'),
    ('eng', 'long', 'Autumn leaves swirl in the gusts, painting the ground with fiery colors, a fleeting reminder of change''s inevitability and the beauty found in letting go.', 'On the slow journey home, check difficult work in small stages before errors become expensive. At the same time, repeated mistakes often reveal a weak process rather than a careless person.'),
    ('eng', 'long', 'The distant sound of church bells echoes through the misty morning, marking time and calling the faithful to reflection, a ritual that anchors us amid life''s uncertainties.', 'Near the end of day, the light from distant lamps turns a brief pause into a lasting memory. After the final note, the warmth beside an empty chair shows that healing often arrives without noise. While turning a page, the letter in the mailbox makes the familiar world feel new again.'),
    ('eng', 'long', 'Golden fields stretch to the horizon, bathed in late afternoon light, whispering stories of harvest, hard work, and the quiet dignity of nature''s cycles.', 'Do not trust the words final chance because we can still write another scene. When no answer can be certain, we did not lose time as much as we lost the courage to speak honestly.'),
    ('eng', 'long', 'The crack of thunder rolls across the sky, a powerful reminder of nature''s might and the smallness of human worries in the face of the earth''s ancient forces.', 'After making a new exercise plan, cleaning a drawer reveals missing objects and forgotten plans in equal numbers. At the same time, after three alarms, even a sleepy person becomes serious near fresh coffee.'),
    ('eng', 'long', 'The old clock ticks steadily in the background, marking the passage of time with impartiality, a constant companion in the ever-changing landscape of human experience.', 'Careful readers mark both the important lines and the parts they do not understand, and people who are willing to ask questions often discover the deeper answer.'),
    ('eng', 'long', 'A warm breeze carries the laughter of distant children, a joyful melody that cuts through the gray monotony of the day and reminds me of life''s simple pleasures.', 'When an unexpected problem appears, finding one improvement makes an ordinary day worth remembering, and when the goal feels distant, finish the next task within reach.'),
    ('eng', 'short', 'A well-defined problem is already partly solved.', 'After a small success, rest can be a wise part of progress rather than a sign of surrender.'),
    ('eng', 'long', 'Respect often appears in the way we handle another person’s time. Arriving prepared, answering honestly, and warning someone early about a delay are small actions that make cooperation feel safe.', 'When the familiar method fails, if focus disappears, close the extra screens and keep one task visible. Finishing a quick task now can remove hours of unnecessary worry.'),
    ('eng', 'long', 'A crowded schedule may be a sign that choices have not been made. Removing one low-value commitment can create more progress than squeezing another task into a day that already has no room.', 'Sincerity often appears in the simple habit of keeping a promised time, and gratitude should be spoken aloud even in the relationships that feel most familiar.'),
    ('kor', 'short', '제 입으로 부르고도 스스로 그 엄청난 돈 액수에 놀래었다.', '도망칠 기회가 생겼을 때, 돌아갈 수 없다면 앞으로 가자 적어도 길은 우리가 고를 수 있어.'),
    ('kor', 'short', '하는 경멸히 여기는 빛이 있는 것 같았다.', '해가 기울 무렵 창문을 열자 선선한 바람이 방 안으로 천천히 들어왔다.'),
    ('kor', 'short', '아내는 불시에 후회하였다.', '비밀번호를 막 바꾸고 나면, 청소를 시작하면 잃어버린 물건과 잊고 있던 추억이 함께 나온다.'),
    ('kor', 'short', '그 틈으로 여섯 눈이 방안을 향해 쏘았다.', '집으로 돌아가는 길에, 질문을 부끄러워하지 않는 사람이 결국 더 깊은 답을 발견한다.'),
    ('kor', 'short', '하고 치성도 한두 번 드린 것이 아니다.', '월요일 아침에, 속도가 느려도 방향을 잃지 않으면 결국 원하는 곳에 닿는다.'),
    ('kor', 'short', '낼은 요보다 좀 일찍 오셔요, 하고 주먹으로 하품을 끄는 것이다.', '평소와 다른 길을 걷다가, 일정을 잡을 때는 예상 시간보다 조금 넉넉한 여백을 두자.'),
    ('kor', 'short', '눈에 띄는 대로 곡괭이를 잡자 대뜸 달겨들었다.', '누군가의 다정한 한마디는 생각보다 오래 남아 힘든 날의 중심을 잡아 준다.'),
    ('kor', 'short', '그러나 왜 그들 내객은 돈을 놓고 가나?', '가까운 사이일수록 고맙다는 말은 마음속에만 두지 않는 것이 좋다.'),
    ('kor', 'short', '무명 필과 주단 바리가 두 고리짝에 꼭 찼다.', '당연하게 여긴 사실을 다시 보면, 달은 지구에서 조금씩 멀어지며 하루의 길이에도 영향을 준다.'),
    ('kor', 'short', '앓는 어미 곁에서 배고파 보채는 개똥이(세 살먹이)에게 죽을 사줄 수도 있다.', '다시 시작하고 싶은 날에, 완료의 기준을 먼저 정하면 불필요한 수정이 크게 줄어든다.'),
    ('kor', 'short', '빌어먹을 것 되는 대로 되어라.', '낯선 동네를 지나다가 길모퉁이의 작은 꽃은 멀어진 마음을 다시 돌아보게 한다.'),
    ('kor', 'short', '그러면 바람 소리였구먼.', '끝이라고 믿었던 장면에서, 돌아갈 수 없다면 앞으로 가자 적어도 길은 우리가 고를 수 있어.'),
    ('kor', 'short', '키스''가 너무 길지 않아요.', '서랍을 정리하다 발견한 사진 속에서 오래전의 내가 환하게 웃고 있었다.'),
    ('kor', 'short', '내가 머리가 터지도록 매를 얻어맞은 것이 이 때문이다.', '일찍 자겠다는 다짐은 밤이 깊을수록 더 철학적인 문장이 된다.'),
    ('kor', 'short', '그리고 행길로 난 유리창을 두드리며, 이상, 하는 것이다.', '비가 그친 오후에, 새로운 언어는 완벽한 문장보다 자주 쓰는 짧은 표현에서 가까워진다.'),
    ('kor', 'short', '남편에게 저녁을 갖다주고 딱하게 바라본다.', '다시 시작하고 싶은 날에, 잠시 쉬는 것은 포기가 아니라 더 오래 가기 위한 선택이다.'),
    ('kor', 'short', '육신이 흐느적흐느적하도록 피로했을 때만 정신이 은화처럼 맑소.', '긴 회의가 끝난 뒤에, 대화가 꼬였을 때는 반박보다 상대의 말을 다시 확인해 보자.'),
    ('kor', 'short', '나가거라, 냉큼 꼴 치워.', '한 번의 실패가 나를 설명하지 않으며 다시 시작하는 마음이 더 오래 남는다.'),
    ('kor', 'short', '웃음 소리들은 높아졌다.', '익숙함이 무심함으로 바뀌기 전에, 서로 다른 의견은 관계의 끝이 아니라 이해의 시작이 될 수 있다.'),
    ('kor', 'short', '말을 하려다가 나를 곁눈으로 흘끗 보고 그만 입을 닫친다.', '과학의 시선으로 세상을 보면, 나무는 뿌리 주변의 균류와 영양분을 주고받으며 함께 살아간다.'),
    ('kor', 'short', '숨소리가 씨근씨근 한다.', '다시 시작하고 싶은 날에, 자료를 공유할 때는 결론과 근거와 다음 순서를 함께 적는 것이 좋다.'),
    ('kor', 'short', '그들의 머리 속에는 한결같이 ''로맨틱''한 생각이 떠올랐다.', '책장을 천천히 넘기다가 거리의 느린 그림자는 마음 한쪽에 잔잔한 여운을 남긴다.'),
    ('kor', 'short', '이렇게 맹세를 하며 부랴부랴 지게를 지고 일터로 갔다.', '지금 손을 놓으면 편해지겠지만 나는 편한 결말을 원하지 않아.'),
    ('kor', 'short', '또 무얼, 하고 좀 떠름했으나 그래도 한 달포 만에 만나니 우선 반갑다.', '저녁 식사를 마친 뒤 불을 낮추니 집 안의 시간이 조금 느리게 흐르는 듯했다.'),
    ('kor', 'short', '요즘 와서는 무턱대고 공연스리 골만 내는 남편이 역 딱하였다.', '간식이 자꾸 생각날 때, 정리하려고 꺼낸 물건이 더 많아졌다면 계획은 잠시 성장 중이다.'),
    ('kor', 'short', '그 때 벙어리 속에는 몇 푼이나 되는지 모르겠으나 고 은화들이 꽤 들어 있었다.', '다시 시작하고 싶은 날에, 모르는 것을 정확히 말할 수 있을 때 배움은 더 빠르게 시작된다.'),
    ('kor', 'short', '물건 가지고 나꾸었나부지.', '집으로 돌아가는 길에, 잠시 쉬는 것은 포기가 아니라 더 오래 가기 위한 선택이다.'),
    ('kor', 'short', '그르렁거리는 숨소리조차 들을 수 없다.', '계획이 어긋난 날에, 기억해야 할 생각은 머릿속에 두지 말고 바로 적어 두자.'),
    ('kor', 'short', '하나는 이글이글 만발한 꽃 같고 하나는 시들시들 마른 낙엽 같다.', '매일 같은 길을 걷더라도 마음의 속도를 늦추면 전에는 없던 풍경이 보인다.'),
    ('kor', 'short', '하건만 같이 있어본 날을 헤아리면 단 일년이 될락말락 한다.', '서운함을 쌓아 두기보다 작을 때 솔직하게 나누는 편이 관계를 지킨다.'),
    ('kor', 'short', '이때에 그 괴상한 소리는 땍대굴 웃었다.', '우리가 보는 별빛은 먼 우주가 오래전에 보낸 소식이다.'),
    ('kor', 'short', '하고 등을 뚜덕여 줄 사람이 누구냐.', '새로운 일을 앞두고, 완료의 기준을 먼저 정하면 불필요한 수정이 크게 줄어든다.'),
    ('kor', 'short', '그나마 참례 못 가는 두꺼비는 빈방에서 개 밥의 도토리로 끙끙거리고.', '회의가 끝난 뒤 문틈으로 든 바람은 서두르던 걸음을 잠시 멈추게 한다.'),
    ('kor', 'short', '열흘이 썩 넘어도 산신은 깜깜 무소식이었다.', '누가 먼저였는지는 중요하지 않아 끝까지 남는 사람이 필요해.'),
    ('kor', 'short', '쾌감이라면 어떤 종류의 쾌감일까를 계속하여 연구하였다.', '따뜻한 차를 우려 놓고 창밖의 빗방울이 흘러내리는 모습을 지켜보았다.'),
    ('kor', 'short', '아비 어미란 말에 가슴이 터지는 것도 같았으나 제겐 아버지가 없어요.', '비밀번호를 막 바꾸고 나면, 알람을 세 번 미룬 사람도 커피 앞에서는 제법 진지해진다.'),
    ('kor', 'short', '그런데 여보게, 자네 왼몸이 어째 물독에 빠진 새앙쥐 같은가?', '혼자 결정하기 어렵다면, 익숙한 방법이 막힐 때 다른 관점은 새로운 출발점이 된다.'),
    ('kor', 'short', '내가 안으로 들어갈 적에 낯선 사람들이 나를 흘끔흘끔 본다.', '마음이 흔들릴 때마다 이 조용한 장면으로 돌아올 수 있을 것 같았다.'),
    ('kor', 'short', '내가 어지간히 알아맞췄지요 하는 모양이었다.', '다시 시작하고 싶은 날에, 집중이 흐트러지면 화면을 닫고 해야 할 일 하나만 남겨 보자.'),
    ('kor', 'short', '세 처녀는 얼굴을 마주 보았다.', '가까운 사람일수록 익숙함 뒤에 숨은 고마움을 자주 표현해야 한다.'),
    ('kor', 'short', '하고, 귀를 뒤로 잡아댕기며 마냥 우는 것이 아니냐.', '가까운 사람과 대화할 때, 서로 다른 의견은 관계의 끝이 아니라 이해의 시작이 될 수 있다.'),
    ('kor', 'short', '오늘 밤 일도 아마 헛물켜나 보다.', '보이지 않는 원리를 생각하면, 나무는 뿌리 주변의 균류와 영양분을 주고받으며 함께 살아간다.'),
    ('kor', 'short', '오늘만 좀 해보고 고만두겠어유.', '새로운 일을 앞두고, 어려운 업무일수록 중간 결과를 자주 확인하는 편이 안전하다.'),
    ('kor', 'short', '나는 내 이불을 뒤집어쓰고 이번에는 참 늘어지게 한잠 잤다.', '골목을 스치는 저녁 바람은 작은 용기를 다시 꺼내 들게 한다.'),
    ('kor', 'short', '이지러는 졌으나 보름을 갓 지난 달은 부드러운 빛을 흔붓이 흘리고 있다.', '정답 없는 질문 앞에서도, 돌아갈 수 없다면 앞으로 가자 적어도 길은 우리가 고를 수 있어.'),
    ('kor', 'short', '흐리고 비오는 하늘은 어둠침침하게 벌써 황혼에 가까운 듯하다.', '첫눈이 내린 거리는 익숙한 풍경을 새하얀 장면으로 천천히 바꾸어 놓았다.'),
    ('kor', 'short', '오늘 저녁 차로 떠날 것이니까 가서 짐을 매어야지.', '월요일 아침이 찾아오면, 비밀번호를 바꾼 직후 옛 비밀번호가 가장 또렷하게 기억난다.'),
    ('kor', 'short', '그 먹고 난 뒤에 괴로운 것이야 겪어본 사람이 아니면 알 수 없지.', '누군가의 도움이 필요할 때, 새로운 언어는 완벽한 문장보다 자주 쓰는 짧은 표현에서 가까워진다.'),
    ('kor', 'short', '도깨비가 났단 말인가?', '하루를 마무리하기 전에, 잠시 쉬는 것은 포기가 아니라 더 오래 가기 위한 선택이다.'),
    ('kor', 'short', '장인 입에서 할아버지 소리가 나오도록 해?', '누군가의 도움이 필요할 때, 좋은 기록은 결과뿐 아니라 그때의 판단 이유까지 남긴다.'),
    ('kor', 'short', '그 꼴을 봐하니 가여운 생각이 안 나는 것도 아니다.', '혼자 보내는 시간은 외로움이 아니라 내 목소리를 다시 듣는 여백이 된다.'),
    ('kor', 'short', '영식이는 낯이 붉어지며 가까스로 한마디하였다.', '미안한 마음을 전해야 한다면, 서로 다른 의견은 관계의 끝이 아니라 이해의 시작이 될 수 있다.'),
    ('kor', 'short', '니코틴이 내 횟배 앓는 뱃속으로 스미면 머릿속에 으레 백지가 준비되는 법이오.', '과학의 시선으로 세상을 보면, 벌은 춤의 방향과 속도로 먹이가 있는 위치를 동료에게 알린다.'),
    ('kor', 'short', '그 꼴에 우리들과 한몫 보자는 셈이지.', '답을 찾기 어려운 순간에, 좋은 피드백은 평가보다 다음 시도를 구체적으로 보여 준다.'),
    ('kor', 'short', '얼마만에 기차는 왔고, 수십 명이나 되는 손이 정류장으로 쏟아져 나왔다.', '오랜 약속을 마치고 책상 위 짧은 메모는 내일의 나에게 다정한 약속을 건넨다.'),
    ('kor', 'short', '비단옷도 해주고 싶고 좋은 양산도 사주고 싶어요!', '세상이 조용해진 뒤에도 네 목소리만은 분명하게 들렸어.'),
    ('kor', 'short', '아니다, 다르다면 다른 점도 있다.', '비가 그친 골목에는 젖은 나무 냄새와 부드러운 저녁빛이 함께 머물렀다.'),
    ('kor', 'short', '아무 까닭 없이 그런 편지를 받은 학생이야말로 큰 재변이었다.', '정리를 시작하고 나면, 알람을 세 번 미룬 사람도 커피 앞에서는 제법 진지해진다.'),
    ('kor', 'short', '나는 잠시 동안 어떻게 되는 심판인지 맥을 몰라서 그 뒷모양만 덤덤히 바라보았다.', '집으로 돌아가는 길에, 한 번에 오래 공부하기보다 짧게 나누어 반복하는 편이 기억에 잘 남는다.'),
    ('kor', 'short', '내가 학교에 다니는 것은 혹 시험 전날 밤새는 맛에 들렸는지 모른다.', '답을 찾기 어려운 순간에, 목표가 멀게 느껴질수록 지금 끝낼 수 있는 일에 집중하자.'),
    ('kor', 'short', '큰 줄이란 본시 산운 산을 끼고 도는 법이다.', '누군가의 도움이 필요할 때, 해야 할 일이 많다면 가장 작은 일 하나부터 끝내 보자.'),
    ('kor', 'short', '그렇건만 나에게는 옷이 없었다.', '기다림은 답이 없는 시간이 아니라 마음이 스스로를 정리하는 과정일 수 있다.'),
    ('kor', 'short', '내일은 진부와 대화에 장이 선다.', '좋아하는 사람을 바라볼 때, 좋아하는 마음은 상대를 바꾸기보다 있는 모습으로 바라볼 때 깊어진다.'),
    ('kor', 'short', '정거장을 떠나는 그의 발길은 힘 하나 없었다.', '당연하게 여긴 사실을 다시 보면, 번개가 보인 뒤 천둥이 늦게 들리는 것은 빛이 소리보다 빠르기 때문이다.'),
    ('kor', 'short', '막벌이꾼한테 시집을 갈 것이지 누가 내게 시집을 오랬어!', '긴 회의가 끝난 뒤에, 막힌 일을 오래 붙들기보다 질문을 정확히 만드는 편이 빠를 때가 있다.'),
    ('kor', 'short', '내가 술이 먹고 싶어서 먹었단 말이요?', '잠에서 막 깨어나 멀리 켜진 불빛은 마음 한쪽에 잔잔한 여운을 남긴다.'),
    ('kor', 'short', '스승과 제자는 조그마한 책상 하나를 새에 두고 마주앉는다.', '마지막 불빛만 남았을 때, 우리가 잃은 것은 시간이 아니라 서로에게 말할 용기였어.'),
    ('kor', 'short', '나중에는 겨우 손톱으로 목을 따라고까지 하고, 제 아들같이 함부로 훅닥이었다.', '우연히 재생된 옛 노래가 잊고 있던 어느 계절의 공기를 데려왔다.'),
    ('kor', 'short', '비탈길을 얼마 올라가서야 콩밭은 놓였다.', '냉장고 앞에 멈춰 서면, 운동을 결심한 날에는 운동복이 평소보다 유난히 멋져 보인다.'),
    ('kor', 'short', '나는 다시 눈을 감고 이불을 푹 뒤집어쓰고 낮잠을 자기에 착수하였다.', '익숙한 방법이 막히면, 새로운 언어는 완벽한 문장보다 자주 쓰는 짧은 표현에서 가까워진다.'),
    ('kor', 'short', '착실한 녀석인 줄 알았더니.', '시간이 부족하게 느껴지면, 스스로를 믿는 연습도 다른 능력처럼 매일 조금씩 좋아진다.'),
    ('kor', 'short', '궂은 비는 의연히 추적추적 내린다.', '다시 시작하고 싶은 날에, 좋은 기록은 결과뿐 아니라 그때의 판단 이유까지 남긴다.'),
    ('kor', 'short', '취한 소리로 중얼거리었다.', '모든 관계에는 말보다 침묵으로 서로를 이해해야 하는 순간이 찾아온다.'),
    ('kor', 'short', '그러면 패가망신하고 만다.', '서운한 마음이 생겼다면, 가까운 사이일수록 고맙다는 말은 마음속에만 두지 않는 것이 좋다.'),
    ('kor', 'short', '나는 언젠가 한번 들어본 법도 하구먼.', '알려진 사실을 천천히 살펴보면, 구름은 가벼워 보여도 큰 구름 하나에는 엄청난 양의 물이 들어 있다.'),
    ('kor', 'short', '자넨 물론 아들이 늦을 걸 염려하지만 점순이루 말하면 이제 겨우 열여섯이 아닌가.', '잠깐 숨을 고르며, 업무의 우선순위는 급한 목소리보다 실제 영향으로 판단해야 한다.'),
    ('kor', 'short', '그는 어쓴 위풍을 보이며 이렇게 분부하였다.', '해가 기울 무렵 빈 의자 옆의 온기는 사소한 행복이 가까이 있음을 알려 준다.'),
    ('kor', 'short', '나는 이 지느러미 수효를 헤어 보기도 하면서 굽힌 허리를 좀처럼 펴지 않았다.', '마지막 불빛만 남았을 때, 불빛이 하나 남아 있다면 아직 돌아갈 길도 남아 있는 거야.'),
    ('kor', 'short', '모친의 친정은 원래부터 제천이었던가?', '비어 있던 우편함에서 반가운 편지 한 통을 발견하고 한참을 바라보았다.'),
    ('kor', 'short', '중대가리는 히히 웃고 치삼을 보며 문의하는 듯이 눈짓을 하였다.', '비밀번호를 막 바꾸고 나면, 회의가 길어질수록 모두가 시계를 보지 않는 기술만 늘어난다.'),
    ('kor', 'short', '아내는 인사를 차리느라고 이런 칭찬은 하나마 별로 부러워하는 기색이 없다.', '월요일 아침에, 모르는 것을 정확히 말할 수 있을 때 배움은 더 빠르게 시작된다.'),
    ('kor', 'short', '아내는 눈만 비비고 서 있다.', '실수가 마음에 남는다면, 두려움이 사라지기를 기다리지 말고 두려움과 함께 한 걸음 내딛자.'),
    ('kor', 'short', '당신 같은 사내는 난 싫어요.', '월요일 아침에, 중요한 결정은 피곤한 밤보다 맑은 아침에 내리는 편이 낫다.'),
    ('kor', 'short', '다시 고개를 들었을 때 그때엔 나도 온몸에 약이 올랐다.', '행복은 대단한 장면보다 좋아하는 사람과 나눈 짧은 웃음 속에 자주 숨어 있다.'),
    ('kor', 'short', '인제 좌지가 나서 낯을 들고 나아갈 염의조차 없어졌다.', '서운한 마음이 생겼다면, 진심은 거창한 표현보다 약속한 시간을 지키는 태도에서 보인다.'),
    ('kor', 'short', '그것이 그저 한없이 야속하고 슬펐다.', '세상이 움직이는 방식을 보면, 문어의 심장은 세 개이며 그중 두 개는 아가미로 피를 보낸다.'),
    ('kor', 'short', '허 생원은 숨이 차 몇 번이고 다리를 쉬지 않으면 안되었다.', '집으로 돌아가는 길에, 업무의 우선순위는 급한 목소리보다 실제 영향으로 판단해야 한다.'),
    ('kor', 'short', '김 첨지의 눈은 벌써 개개 풀리기 시작하였다.', '낯선 동네를 지나다가 골목에서 만난 바람은 내일의 나에게 다정한 약속을 건넨다.'),
    ('kor', 'short', '그러나 무엇에 상당한 자극만 받으면 참고 참았던 이런 소리를 하게 되는 것이다.', '도망칠 기회가 생겼을 때, 누가 먼저였는지는 중요하지 않아 끝까지 남는 사람이 필요해.'),
    ('kor', 'short', '-문득 기막힌 듯이 외마디 소리를 치고는 벌떡 몸을 일으킨다.', '바닷가에 앉아 밀려왔다 멀어지는 파도의 리듬을 오래 바라보았다.'),
    ('kor', 'short', '아마 미쳤나보아, 밤중에 혼자 일어나서 왜 저리고 있을꾸.', '비밀번호를 막 바꾸고 나면, 간식은 배가 고플 때보다 일이 어려울 때 더 설득력 있게 다가온다.'),
    ('kor', 'short', '부려만 먹구 왜 성례 안하지유!', '익숙한 방법이 막히면, 익숙한 방법이 막힐 때 다른 관점은 새로운 출발점이 된다.'),
    ('kor', 'short', '군말 없이 지시해 받은 곳에다 삽을 폭 꽂고 파헤치기 시작하였다.', '비가 그친 오후에, 아직 서툴다는 사실은 앞으로 달라질 여지가 많다는 뜻이다.'),
    ('kor', 'short', '나서서 나는 또 문득 생각하여 보았다.', '익숙한 방법이 막히면, 일정을 잡을 때는 예상 시간보다 조금 넉넉한 여백을 두자.'),
    ('kor', 'short', '철 들어서부터 맞기 시작한 것이 하룬들 편한 날 있었을까.', '슬픔을 억지로 지우기보다 충분히 지나가게 두는 것이 진짜 회복에 가깝다.'),
    ('kor', 'short', '여보게 돈 떨어졌네, 왜 돈을 막 끼얹나.', '미안한 마음을 전해야 한다면, 힘든 사람에게 필요한 것은 해결책보다 곁에 남아 주는 시간일 때가 있다.'),
    ('kor', 'short', '동부인 아니하고 오실라구!', '구름은 가벼워 보여도 큰 구름 하나에는 엄청난 양의 물이 들어 있다.'),
    ('kor', 'short', '남편은 문득 미끄러지는 듯이 벽을 타고 내려앉는다.', '좋은 피드백은 평가보다 다음 시도를 구체적으로 보여 준다.'),
    ('kor', 'short', '하학하기가 무섭게 그 학생은 사감실로 불리어 간다.', '해가 기울 무렵 문틈으로 든 바람은 평범한 순간의 소중함을 다시 알려 준다.'),
    ('kor', 'short', '참말 난 일 안해서 징역 가도 좋다 생각했다.', '모두가 포기하라고 말해도, 마지막 기회라는 말은 믿지 마 다음 장면은 우리가 만드는 거니까.'),
